{
}

const char *MMIXInstructionSelector::getName() { return DEBUG_TYPE; }

/**
 * @brief Break a 64-bit unsigned integer to 4 parts
 * each part is 16-bit, from hi to lo
 *
 * @param V
 * @return std::array<uint16_t, 4>
 */
static std::array<uint16_t, 4> breakUInt64(uint64_t V) {
  std::array<uint16_t, 4> Parts;
  for (int I = 0; I != 4; ++I)
    Parts[I] = V >> (3 - I) * 16;
  return Parts;
}

static bool selectG_CONSTANT(MachineInstr &I) {
  assert((I.getOpcode() == TargetOpcode::G_CONSTANT ||
          I.getOpcode() == TargetOpcode::G_FCONSTANT) &&
         "expect G_F?CONSTANT");
  MachineIRBuilder MIB(I);
  MachineRegisterInfo &MRI = *MIB.getMRI();
  unsigned Ops[4] = {0, MMIX::ORMH, MMIX::ORML, MMIX::ORL};
  MachineOperand ImmOperand = I.getOperand(1);
  uint64_t Constant = ImmOperand.isCImm() ? ImmOperand.getCImm()->getZExtValue()
                                          : ImmOperand.getFPImm()
                                                ->getValue()
                                                .bitcastToAPInt()
                                                .trunc(64)
                                                .getZExtValue();
  std::array Parts = breakUInt64(Constant);

  Register ResultReg =
      MRI.createVirtualRegister(&getMMIXMCRegisterClass(MMIX::GPRRegClassID));
  MIB.buildInstr(MMIX::SETH).addDef(ResultReg).addImm(Parts[0]);
  for (int I = 1; I != 4; ++I) {
    uint64_t Imm = Parts[I];
    if (Imm == 0)
      continue;
    Register TmpReg =
        MRI.createVirtualRegister(&getMMIXMCRegisterClass(MMIX::GPRRegClassID));
    MIB.buildInstr(Ops[I])
        .addDef(TmpReg)
        .addUse(ResultReg, RegState::Kill)
        .addImm(Imm);
    ResultReg = TmpReg;
  }
  MRI.replaceRegWith(I.getOperand(0).getReg(), ResultReg);
  I.eraseFromParent();
  return true;
}

bool MMIXInstructionSelector::select(MachineInstr &I) {
  LLVM_DEBUG(dbgs() << "select ");
  LLVM_DEBUG(I.dump());

  unsigned Opc = I.getOpcode();
  // Certain non-generic instructions also need some special handling.
  if (!isPreISelGenericOpcode(Opc))
    return true;

  if (selectImpl(I, *CoverageInfo))
    return true;

  switch (Opc) {
  case TargetOpcode::G_CONSTANT:
    return selectG_CONSTANT(I);
  case TargetOpcode::G_FCONSTANT:
    return selectG_CONSTANT(I);
  default:
    break;
  }

  return false;
}
